const cases = [bc, sk, ab]
const validation = validateProvincialCaseSet(cases, registry)

const mdLink = source => `[${source.title}](${source.url})`
const bullet = items => items.length ? items.map(item => `- ${item}`).join("\n") : "- None documented."
const caseReport = record => `# ${record.identity.canonical_name}\n\n> Private owner-review dossier. No publication or production mutation is authorized.\n\n## What happened\n\n${record.owner_view.what_happened}\n\n## Why this matters\n\n${bullet(record.owner_view.why_this_matters)}\n\n## The one thing to remember\n\n${record.owner_view.one_thing_to_remember}\n\n## Review first\n\n${bullet(record.owner_view.review_first)}\n\n## Review next\n\n${bullet(record.owner_view.review_next)}\n\n## Timeline\n\n${bullet(record.timeline.map(item => `${item.date_or_range} — **${item.title}.** ${item.short_description}`))}\n\n## Accountability chain\n\n${bullet(record.evidence_graph.edges.map(item => `${item.from_object_id} → **${item.relationship_type}** → ${item.to_object_id}: ${item.neutral_summary}`))}\n\n## Who is involved\n\n${bullet(record.organizations.map(item => `${item.name} — ${item.role}`))}\n\n## Government / policy / law\n\n${bullet((record.policy_law_governance || record.legal_policy_context || []).map(item => `${item.title} (${item.context_scope}): ${item.summary}${item.boundary ? ` Boundary: ${item.boundary}` : ""}`))}\n\n## What changed\n\n${bullet(record.implementation_evidence.map(item => `${item.depth}: ${item.summary}`))}\n\n## What we know\n\n${bullet(record.owner_view.what_we_know)}\n\n## What remains uncertain\n\n${bullet(record.owner_view.what_remains_uncertain)}\n\n## Next question\n\n${bullet(record.owner_view.next_questions)}\n\n## Owner assessment\n\nSignificance: ${record.owner_assessment.significance}. Confidence: ${record.owner_assessment.confidence}. Owner review: ${record.owner_assessment.owner_review ? "required" : "not currently required"}.\n\nRecommended next move: ${record.owner_view.recommended_next_move}\n\n## Sources\n\n${bullet(record.sources.map(mdLink))}\n\n## Limitations\n\n${record.limitations}\n`

const brief = (record, title) => `# ${title}\n\n> Private research brief for owner review. Not published.\n\n## Executive summary\n\n${record.owner_view.what_happened} ${record.owner_view.one_thing_to_remember}\n\n## Scope\n\nThis brief follows one documented Miller North subject through accountability, government, policy or law, implementation and later public evidence. It includes only source-backed dimensions and does not provide legal advice.\n\n## Timeline\n\n${bullet(record.timeline.map(item => `${item.date_or_range}: ${item.title} — ${item.short_description}`))}\n\n## Key findings\n\n${bullet([...record.owner_view.review_first, ...record.owner_view.review_next].slice(0, 5))}\n\n## Government, policy and accountability\n\n${bullet(record.evidence_graph.edges.map(item => item.neutral_summary))}\n\n## Implementation\n\n${bullet(record.implementation_evidence.map(item => `${item.depth}: ${item.summary}`))}\n\n## Unresolved questions\n\n${bullet(record.owner_view.what_remains_uncertain)}\n\n## Method\n\nThe Farm began with existing private chains, searched forward and backward through registered authoritative source families, required a source on every material edge, ran one bounded knowledge-gap follow-up, and stopped when authoritative sources answered the question or further public searching showed diminishing returns.\n\n## Sources\n\n${bullet(record.sources.map(mdLink))}\n\n## Limitations\n\n${record.limitations}\n`

const writeJson = (name, value) => writeFileSync(resolve(out, name), `${JSON.stringify(value, null, 2)}\n`)
const writeMd = (name, value) => writeFileSync(resolve(out, name), value)

writeJson("miller-north-provincial-case-british-columbia-in-plain-sight-2026-09-06.json", bc)
